mapper.select:
  SELECT COUNT(*)
  FROM "MP_IPMS_PA".utb_progress a
  WHERE a.office_seq = #{officeSeq}
AND a.tbl_seq = #{conflictSeq}
    AND a.del_yn = 'N'

SELECT /* [1. 심판/분쟁 마스터 (기본 컬럼명 유지)] */ c.conflict_seq, c.office_seq, c.app_seq, c.litigation_case_no, c.asset_no AS ourRef, c.agent_ref AS yourRef, c.case_title_ko, -- 계류법정 c.court_category_code, fn_get_cd_nm('COURT_TYPE', c.court_category_code) AS court_category_code_name, c.case_category_code AS appClassificationCode, fn_get_cd_nm('NAT_IO_DIV', c.case_category_code) AS appClassificationCodeName, -- 대리인구분 c.agent_category_code, fn_get_cd_nm('AGENT_TYPE', c.agent_category_code) AS agent_category_code_name, -- 사건종류구분 c.case_type_code, fn_get_cd_nm('CASE_TYPE_TRIAL', c.case_type_code) AS case_type_code_name, -- 진행상태 c.status, fn_get_cd_nm('STATUS', c.status) AS statusCodeName, c.litigation_case_no AS caseNo, c.respondent_name AS respondent, c.petitioner_type, c.petitioner_memo, c.respondent_type, c.respondent_memo, c.respondent_name AS respondent, c.pre_exam_result, c.final_result, c.decision_content, c.appeal_content, c.abandon_yn AS isAbandoned , c.abandon_content, c.dept_name, c.introducer, c.note, c.del_yn, c.create_user, to_char(c.create_at, 'YYYYMMDD') AS create_at, to_char(c_due."claimDate", 'YYYYMMDD') AS claimDate, to_char(c_due."preExamDate", 'YYYYMMDD') AS preExamDate, to_char(c_due."amendLimitDate", 'YYYYMMDD') AS amendLimitDate, to_char(c_due."amendSubmitDate", 'YYYYMMDD') AS amendSubmitDate, to_char(c_due."judgmentServedDate", 'YYYYMMDD') AS judgmentServedDate, to_char(c_due."appealLimitDate", 'YYYYMMDD') AS appealLimitDate, to_char(c_due."appealDate", 'YYYYMMDD') AS appealDate, to_char(c_due."abandonInstructDate", 'YYYYMMDD') AS abandonInstructDate, to_char(c_due."abandonDate", 'YYYYMMDD') AS abandonDate,
/* [2. 출원 마스터 정보] */ app.app_no, app.reg_no, app.country_code, app.domestic_reg_no, fn_get_ctry_nm(app.country_code, 'C', 'KO') AS country_code_name, --app.app_classification AS caseTypeCode, --fn_get_cd_nm('NAT_IO_DIV', app.app_classification ) AS caseTypeCodeName, app.product_class AS goodsClass, -- app.app_country, app.right_category AS rightTypeCode, fn_get_cd_nm('PAT_TYPE', app.right_category ) AS rightTypeCodeName, app.retain_seq AS clientRef, app.app_name_ko AS titleKo, app.app_name_en AS titleEn, /* [3. 심판 단계 날짜 및 관계자 (c.conflict_seq 기준)] */ to_char(c_due."receiptDate", 'YYYYMMDD') AS receiptDate, to_char(c_due."dueLimitDate", 'YYYYMMDD') AS dueLimitDate, to_char(c_due."judgmentDate", 'YYYYMMDD') AS judgmentDate, to_char(c_due."processDate", 'YYYYMMDD') AS processDate, -- to_char(c_due."deadlineDate", 'YYYYMMDD') AS deadlineDate, to_char(a_due."abandonDate", 'YYYYMMDD') AS abandonDate,
COALESCE( c.client, c_pp."client_NM", (SELECT COALESCE(NULLIF(client_name_ko, ''), company_name) FROM "MP_IPMS_PA".utb_customer WHERE customer_seq = c_pp."client" AND del_yn = 'N') ) AS clientName, c_pp."client" AS client, c_pp."petitioner" AS petitioner, c_pp."petitioner_NM" AS petitionerName, -- c_pp."respondent" AS respondent, -- c_pp."respondent_NM" AS respondentName, c_pp."adminMgr" AS adminMgr, c_pp."adminMgr_NM" AS adminMgrName, c_pp."caseMgr" AS caseMgr, c_pp."caseMgr_NM" AS caseMgrName, c_pp."attorney" AS attorney, c_pp."attorney_NM" AS attorneyName, COALESCE( c.foreign_agent, c_pp."foreignAgent_NM", (SELECT COALESCE(NULLIF(client_name_ko, ''), company_name) FROM "MP_IPMS_PA".utb_customer WHERE customer_seq = c_pp."foreignAgent" AND del_yn = 'N') ) AS foreignAgentName, c_pp."foreignAgent" AS foreignAgent,
/* [4. 출원 단계 날짜 및 관계자 (app.app_seq 기준)] */ to_char(a_due."appDate", 'YYYYMMDD') AS appDate, to_char(a_due."announcementDate", 'YYYYMMDD') AS announcementDate, to_char(a_due."regDate", 'YYYYMMDD') AS regDate, to_char(a_due."regDecisionDate", 'YYYYMMDD') AS domesticRegDecisionDate, to_char(a_due."domesticRegDate", 'YYYYMMDD') AS domesticRegDate, to_char(a_due."intlPubDate", 'YYYYMMDD') AS intlRegDate,
a_pp."applicant" AS applicant, COALESCE( a_pp."applicant_NM", (SELECT COALESCE(NULLIF(client_name_ko, ''), company_name) FROM "MP_IPMS_PA".utb_customer WHERE customer_seq = a_pp."applicant" AND del_yn = 'N') ) AS applicantName, a_pp."inventor" AS inventor, COALESCE( a_pp."inventor_NM", (SELECT COALESCE(NULLIF(client_name_ko, ''), company_name) FROM "MP_IPMS_PA".utb_customer WHERE customer_seq = a_pp."inventor" AND del_yn = 'N') ) AS inventorName
FROM "MP_IPMS_PA".utb_conflict_mst c /* 출원 마스터 조인 */ LEFT JOIN "MP_IPMS_PA".utb_app_mst app ON c.app_seq = app.app_seq AND c.office_seq = app.office_seq
/* --- 심판(Conflict)용 뷰 조인 --- */ LEFT JOIN "MP_IPMS_PA".v_total_duedate_pivot c_due ON c.conflict_seq = c_due.tbl_seq AND c.office_seq = c_due.office_seq LEFT JOIN "MP_IPMS_PA".v_participant_pivot c_pp ON c.conflict_seq = c_pp.tbl_seq AND c.office_seq = c_pp.office_seq
/* --- 출원(App)용 뷰 조인 --- */ LEFT JOIN "MP_IPMS_PA".v_total_duedate_pivot a_due ON app.app_seq = a_due.tbl_seq AND app.office_seq = a_due.office_seq LEFT JOIN "MP_IPMS_PA".v_participant_pivot a_pp ON app.app_seq = a_pp.tbl_seq AND app.office_seq = a_pp.office_seq
WHERE c.conflict_seq = #{conflictSeq} AND c.office_seq = #{officeSeq} AND c.del_yn = 'N'

SELECT * FROM ( SELECT /* [1. 마스터 정보 (utb_conflict_mst)] */ c.conflict_seq AS "conflictSeq", c.office_seq AS "officeSeq", c.app_seq AS "appSeq", c.asset_no AS "ourRef", c.agent_ref AS "yourRef", c.litigation_case_no AS "caseNo", c.case_title_ko AS "caseTitleKo", c.status AS "statusCode", fn_get_cd_nm('STATUS', c.status) AS "statusCodeName", c.case_type_code AS "caseTypeCode", fn_get_cd_nm('CASE_TYPE_TRIAL', c.case_type_code) AS "caseTypeCodeName", c.court_category_code AS "courtCategoryCode", fn_get_cd_nm('COURT_TYPE', c.court_category_code) AS "courtCategoryCodeName", c.agent_category_code AS "agentCategoryCode", fn_get_cd_nm('AGENT_TYPE', c.agent_category_code) AS "agentCategoryCodeName", c.decision_content AS "decisionContent", c.decision_content AS "judgmentResult", c.abandon_content AS "abandonContent", c.abandon_content AS "abandonNote", c.abandon_yn AS "isAbandoned", c.dept_name AS "deptName", c.note AS "note", c.note AS "memo", c.respondent_name AS "respondent", c.final_result AS "finalResult", c.create_at AS "createAt", /* 정렬용 */ c.create_user AS "createUser", /* 정렬용 */ c.update_user AS "updateUser", /* 정렬용 */ c.etc_yn AS "etcYn", /* [2. 출원 정보 (utb_app_mst)] */ app.app_no AS "appNo", app.reg_no AS "regNo", app.main_drawing_file AS "citedTrademarkImage", app.app_name_ko AS "titleKo", app.app_name_en AS "titleEn", app.country_code AS "countryCode", fn_get_ctry_nm(app.country_code, 'C', 'KO') AS "countryCodeName", app.app_classification AS "appClassificationCode", fn_get_cd_nm('NAT_IO_DIV', app.app_classification) AS "appClassificationCodeName", app.right_category AS "rightTypeCode", fn_get_cd_nm('PAT_TYPE', app.right_category) AS "rightTypeCodeName",
/* [3. 날짜 정보 (이의심판 기일 - due)] */ to_char(due."receiptDate", 'YYYYMMDD') AS "receiptDate", to_char(due."dueLimitDate", 'YYYYMMDD') AS "dueLimitDate", to_char(due."dueLimitDate", 'YYYYMMDD') AS "caseCloseDate", /* 사건마감일 */ to_char(due."dueLimitDate", 'YYYYMMDD') AS "processLimitDate", /* 처리마감일 */ to_char(due."claimDate", 'YYYYMMDD') AS "claimDate", to_char(due."judgmentDate", 'YYYYMMDD') AS "judgmentDate", to_char(due."judgmentDate", 'YYYYMMDD') AS "finishAt", /* 진행완료일 */ to_char(due."appealLimitDate", 'YYYYMMDD') AS "appealLimitDate", to_char(due."appealDate", 'YYYYMMDD') AS "appealDate", to_char(due."abandonDate", 'YYYYMMDD') AS "abandonDate", to_char(due."processDate", 'YYYYMMDD') AS "processDate", to_char(due."processDate", 'YYYYMMDD') AS "completeDate", /* 완료일 */ to_char(due."processDate", 'YYYYMMDD') AS "completeAt", to_char(due."processDate", 'YYYYMMDD') AS "hdrDate", /* HDR처리일 */
/* [4. 날짜 정보 (원출원 기일 - appdue)] */ to_char(appdue."appDate", 'YYYYMMDD') AS "appDate", to_char(appdue."regDate", 'YYYYMMDD') AS "regDate",
/* [5. 관계자 정보 (피벗 뷰 - pp)] */ pp."client" AS "client", COALESCE( pp."client_NM", (SELECT COALESCE(NULLIF(client_name_ko, ''), company_name) FROM "MP_IPMS_PA".utb_customer WHERE customer_seq = pp."client" AND del_yn = 'N') ) AS "clientName", pp."foreignAgent" AS "foreignAgent", COALESCE( pp."foreignAgent_NM", (SELECT COALESCE(NULLIF(client_name_ko, ''), company_name) FROM "MP_IPMS_PA".utb_customer WHERE customer_seq = pp."foreignAgent" AND del_yn = 'N') ) AS "foreignAgentName", pp."petitioner" AS "petitioner", pp."petitioner_NM" AS "petitionerName", pp."adminMgr" AS "adminMgr", pp."adminMgr_NM" AS "adminMgrName", pp."caseMgr" AS "caseMgr", pp."caseMgr_NM" AS "caseMgrName", pp."attorney" AS "attorney", pp."attorney_NM" AS "attorneyName",
/* [6. 진행 정보 (기타사건용)] */ prg.receipt_doc_name AS "receiptDocName", prg.receipt_doc_content AS "receiptDocContent", prg.instruction_content AS "instructionContent", prg.instruction_content AS "orderContent", prg.submit_doc_name AS "submitDocName", prg.submit_doc_name AS "submitDoc", pp_prg."submitManager_NM" AS "submitManagerName", pp_prg."submitManager_NM" AS "submitMgrName" FROM "MP_IPMS_PA".utb_conflict_mst c LEFT JOIN "MP_IPMS_PA".utb_app_mst app ON c.app_seq = app.app_seq AND c.office_seq = app.office_seq LEFT JOIN "MP_IPMS_PA".v_total_duedate_pivot due ON c.conflict_seq = due.tbl_seq AND c.office_seq = due.office_seq LEFT JOIN "MP_IPMS_PA".v_participant_pivot pp ON c.conflict_seq = pp.tbl_seq AND c.office_seq = pp.office_seq LEFT JOIN "MP_IPMS_PA".v_total_duedate_pivot appdue ON c.app_seq = appdue.tbl_seq AND c.office_seq = appdue.office_seq /* 최신 진행 정보 조인 */ LEFT JOIN ( SELECT *, ROW_NUMBER() OVER(PARTITION BY tbl_seq ORDER BY create_at DESC) as rn FROM "MP_IPMS_PA".utb_progress WHERE del_yn = 'N' ) prg ON c.conflict_seq = prg.tbl_seq AND prg.rn = 1 LEFT JOIN "MP_IPMS_PA".v_participant_pivot pp_prg ON prg.progress_seq = pp_prg.tbl_seq AND prg.office_seq = pp_prg.office_seq WHERE c.office_seq = #{request.officeSeq} AND c.del_yn = 'N' ) T
ORDER BY T."createAt" DESC LIMIT #{request.pageSize} OFFSET #{request.offSet}

mapper.delete:
DELETE FROM utb_conflict_result
WHERE conflict_seq = #{conflictSeq}
  AND office_seq   = #{officeSeq}
